shell_commands:
python3 - <<'EOF'
p='src/transport/conversationList.acceptance.test.ts'
s=open(p).read()
s=s.replace("import {captureErrors} from '../shared/logCaptureTestSupport.js';\n","import {setLogger} from '../shared/logger.js';\n")
s=s.replace("const errors = captureErrors();\n\nafterEach(stopEngines);","""const errors: Array<Record<string, unknown>> = [];
const quiet = () => undefined;

// Silenced for the whole file, so a socket closing after a test ends logs nothing; error lines are kept to assert on.
beforeAll(() => {
  setLogger({debug: quiet, info: quiet, warn: quiet, error: (category, message, fields) => void errors.push({category, message, ...fields})});
});

afterAll(() => setLogger());

afterEach(async () => {
  errors.length = 0;
  await stopEngines();
});""")
open(p,'w').write(s)
EOF
npx prettier --write src/transport/conversationList.acceptance.test.ts >/dev/null && NODE_OPTIONS=--experimental-vm-modules npx jest --runTestsByPath src/transport/conversationList.acceptance.test.ts 2>&1 | grep -E "✓|✕|●|Tests:|Cannot log"

python3 - <<'EOF'
p='src/transport/conversationList.acceptance.test.ts'
s=open(p).read()
old="afterAll(() => setLogger());"
assert old in s
s=s.replace(old,"""// Restored only once the last server has seen its sockets close, so no disconnect is logged after the file ends.
afterAll(async () => {
  await new Promise(resolve => setTimeout(resolve, 100));
  setLogger();
});""")
open(p,'w').write(s)
EOF
